const std::vector<Genre>& genres() { return kGenres; }

const Genre* findGenre (const juce::String& id)
{
    for (auto& g : kGenres) if (id == g.id) return &g;
    return nullptr;
}

const Genre& defaultGenre()
{
    return *findGenre ("afrohouse");
}

juce::String camelot (int keyPc, bool major)
{
    // minor: A = 8A and each fifth up adds one (E = 9A, B = 10A...); major: C = 8B
    const int pc = ((keyPc % 12) + 12) % 12;
    const int fromRef = ((pc - (major ? 0 : 9)) * 7 % 12 + 12) % 12;
    return juce::String ((fromRef + 7) % 12 + 1) + (major ? "B" : "A");
}

juce::String keyName (int keyPc, bool major)
{
    static const char* names[] { "Do", "Do#", "Re", "Mib", "Mi", "Fa", "Fa#", "Sol", "Lab", "La", "Sib", "Si" };
    return juce::String (names[((keyPc % 12) + 12) % 12]) + (major ? " mayor" : " menor");
}

juce::StringArray genreFamilies()
{
    juce::StringArray out;
    for (auto& g : kGenres) out.addIfNotAlreadyThere (juce::String::fromUTF8 (g.family));
    return out;
}
